        /* sdd-asis-lifecycle:begin btn_validationForm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.validationForm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16000.btn_validationForm_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_checkPwAjax
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_checkPwAjax = async function () {
    const sbmOptions = {
        id: "tx_checkPwAjax",
        method: "post",
        action: "/main/login.do",
        ref: "dma_checkPwAjaxReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods16000.tx_checkPwAjax" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_emailCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param
