*/
scwin.tx_emailCheck = async function () {
    const sbmOptions = {
        id: "tx_emailCheck",
        method: "post",
        action: "/account/registProc.do",
        ref: "dma_emailCheckReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods16000.tx_emailCheck" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_sendForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_sendForm = async function () {
    const sbmOptions = {
        id: "tx_sendForm",
        method: "post",
        action: "/account/registProc.do?method=registerProcess",
        ref: "dma_sendFormReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods16000.tx_sendForm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.openPwPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openPwPop = function () {
    /* sdd-asis-lifecycle:begin openPwPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/account/pwPop.do?method=passwordPop", unresolved: "nav:" + "/account/pwPop.do?method=passwordPop" }; })();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.cancel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cancel = function () {
    /* sdd-asis-lifecycle:begin cancel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    confirmF("회원가입 신청을 취소 하시겠습니까?", async function() {
            await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /main/main.do). 전환 대상 화면이 확정되면 연결됩니다.');
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.validationForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.validationForm = async function () {
    /* sdd-asis-lifecycle:begin validationForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.frmReg || { elements: [] });
    const usrBelngDepNm = $c.util.getComponent('ipt_usrBelngDepNm');
    const jobtitlNm = $c.util.getComponent('ipt_jobtitlNm');
    if ($c.cm.fn_NullChk(usrBelngDepNm)) {
        return;
    }
    if ($c.cm.fn_NullChk(jobtitlNm)) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_telNo1'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_telNo2'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_cellphoneNo1'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_cellphoneNo2'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_email1'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_telNo1')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_telNo2')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_telNo3')))) {
        await alertE('유선전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_cellphoneNo1')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_cellphoneNo2')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_cellphoneNo3')))) {
        await alertE('휴대전화번호는 숫자만 입력하십시오.');
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_faxNo1')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_faxNo2')) && $c.cm.fn_IsNumber($c.util.getComponent('ipt_faxNo3')))) {
        await alertE('FAX는 숫자만 입력하십시오.');
        return;
    }
    const hiddenEmail = $c.util.getComponent("ipt_hiddenEmail").getValue();
    const chgEmail = $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue());
    if (hiddenEmail !== chgEmail) {
        if ($c.util.getComponent("ipt_emailUseYn").getValue() !== chgEmail) {
            await alertE("이메일 중복여부를 확인하시기 바랍니다.");
            return;
        }
    }
    if (!scwin.checkPwAjax(frm)) {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chngEmailBtn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chngEmailBtn = function () {
    /* sdd-asis-lifecycle:begin chngEmailBtn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.chgBtn.setStyle("display", "none");
    scwin.confBtn.setStyle("display", "");
    (($c.util.getComponent('ipt_email1')) && ($c.util.getComponent('ipt_email1')).setReadOnly ? ($c.util.getComponent('ipt_email1')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
    (($c.util.getComponent('ipt_email2')) && ($c.util.getComponent('ipt_email2')).setReadOnly ? ($c.util.getComponent('ipt_email2')).setReadOnly((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
    (($c.util.getComponent('ipt_email1')) && ($c.util.getComponent('ipt_email1')).removeClass ? ($c.util.getComponent('ipt_email1')).removeClass("bgcolor1") : console.error('[sdd] removeClass 미지원 컴포넌트: ipt_email1'));
    (($c.util.getComponent('ipt_email2')) && ($c.util.getComponent('ipt_email2')).removeClass ? ($c.util.getComponent('ipt_email2')).removeClass("bgcolor1") : console.error('[sdd] removeClass 미지원 컴포넌트: ipt_email2'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.checkPwAjax = scwin.tx_checkPwAjax;

scwin.emailCheck = scwin.tx_emailCheck;

scwin.sendForm = scwin.tx_sendForm;
